SELECT r.name FROM races AS r INNER JOIN circuits AS c ON r.circuitId = c.circuitId INNER JOIN laptimes AS l ON r.raceId = l.raceId WHERE c.name = 'Austrian Grand Prix Circuit' AND l.milliseconds = (SELECT MIN(milliseconds) FROM laptimes INNER JOIN races ON laptimes.raceId = races.raceId WHERE races.circuitId = c.circuitId);

